 dict(id=3396, url='3396-2', name='Moroccan Coastal & Desert Expedition', days=7, start='Marrakech', end='Marrakech',
  img=U+'pexels-mographe-30949484-scaled.jpg', kind='Desert & coast',
  intro='A journey combining Morocco’s deserts, coastal towns, and rich culture — ideal for travelers with 5–10 days to explore.',
  plan=[
  ('Marrakech | Zagora', 'Depart Marrakech early morning, heading south through the Atlas Mountains. Stop at the Kasbah of Ait Ben Haddou, a walled city with six historic kasbahs. Continue to Ouarzazate, home of Atlas Film Studios and famous film locations. Drive through the lush Draa Valley, lined with palm groves and kasbahs, arriving in Zagora for overnight stay at a local hotel.'),
  ('Zagora | Erg Chigaga Sahara Desert', 'Travel two hours south and then two hours off-road to Erg Chigaga, a remote Sahara region. Trek by camel through the dunes to a Berber camp. Dinner and overnight in well-equipped nomad tents or bivouac under the stars.'),
  ('Chigaga | Iriki | Tata | Taroudant', 'After sunrise, drive toward Taroudant, traveling off-road through Erg Chigaga and the Lac Iriki dry lakebed, famous from the Paris-Dakar rally. Stop for lunch at Foum Zguid, continue through the Anti-Atlas argan-tree biosphere reserve, arriving at Taroudant, known as the ‘Grandmother of Marrakech’ for its ramparts and charm.'),
  ('Taroudant | Agadir', 'Morning walking tour of Taroudant’s vibrant markets and ancient city walls. Afterward, drive to Agadir, Morocco’s sunshine capital, through the scenic Sous Valley.'),
  ('Agadir', 'Day dedicated to cycling, guided walks, or beach activities. Visit Croco Park to see 325 Nile crocodiles in a botanical setting, then ride the cable car to the panoramic old kasbah of Agadir. Activities can be customized at booking.'),
  ('Agadir | Essaouira', 'Drive to Essaouira via a beautiful argan forest, spotting goats climbing the trees. Explore the coastal town, stroll along the windy beaches, and watch world-class windsurfers in action.'),
  ('Essaouira | Marrakech', 'Return to Marrakech. End of the Moroccan Coastal and Desert Expedition, highlighting deserts, eco areas, and coastal beauty. Farewell and thanks for choosing Epic Travel Morocco.'),
 ]),
